        JDOMNodePointer pointer = new JDOMNodePointer(null, null);
        assertEquals("text()", pointer.asPath());
    }

    @Test
    public void testAsPathWithProcessingInstruction() {
        JDOMNodePointer pointer = new JDOMNodePointer(null, null);
        assertEquals("processing-instruction('target')", pointer.asPath());
    }
