        }

        @Override
        public QName getQName() {
            return null;
        }

        @Override
        public Pointer getContextNode() {
            return null;
        }
    }

    @Test
    public void testModulusWithPositiveIntegers() {
        ConstantExpression left = new ConstantExpression(10);
        ConstantExpression right = new ConstantExpression(3);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Object result = op.computeValue((EvalContext) null);

        assertTrue(result instanceof Double);
        assertEquals(1.0d, ((Double) result).doubleValue(), 0.0d);
        assertEquals(1, left.getCalls());
        assertEquals(1, right.getCalls());
    }

    @Test
    public void testModulusWithNegativeLeftOperand() {
        ConstantExpression left = new ConstantExpression(-10);
        ConstantExpression right = new ConstantExpression(3);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Object result = op.computeValue((EvalContext) null);

        assertTrue(result instanceof Double);
        assertEquals(-1.0d, ((Double) result).doubleValue(), 0.0d);
    }

    @Test
    public void testModulusWithFloatingPointInputsTruncatesToLong() {
        ConstantExpression left = new ConstantExpression(10.9d);
        ConstantExpression right = new ConstantExpression(3.2d);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Object result = op.computeValue((EvalContext) null);

        assertTrue(result instanceof Double);
        assertEquals(1.0d, ((Double) result).doubleValue(), 0.0d);
    }

    @Test
    public void testModulusReturnsZeroAsDouble() {
        ConstantExpression left = new ConstantExpression(6);
        ConstantExpression right = new ConstantExpression(3);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Object result = op.computeValue((EvalContext) null);

        assertNotNull(result);
        assertTrue(result instanceof Double);
        assertEquals(0.0d, ((Double) result).doubleValue(), 0.0d);
    }

    @Test(expected = ArithmeticException.class)
    public void testModulusByZeroThrowsArithmeticException() {
        ConstantExpression left = new ConstantExpression(6);
        ConstantExpression right = new ConstantExpression(0);
        CoreOperationMod op = new CoreOperationMod(left, right);

        op.computeValue((EvalContext) null);
    }

    @Test(expected = ClassCastException.class)
    public void testNonConvertibleInputThrowsClassCastException() {
        ConstantExpression left = new ConstantExpression("not-a-number");
        ConstantExpression right = new ConstantExpression(2);
        CoreOperationMod op = new CoreOperationMod(left, right);

        op.computeValue((EvalContext) null);
    }

    @Test
    public void testContextIsNotModifiedAndExpressionsEvaluatedOnce() throws Exception {
        DummyEvalContext context = new DummyEvalContext();
        ConstantExpression left = new ConstantExpression(9);
        ConstantExpression right = new ConstantExpression(4);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Object result = op.computeValue((EvalContext) null);

        assertTrue(result instanceof Double);
        assertEquals(1.0d, ((Double) result).doubleValue(), 0.0d);
        assertEquals(0, context.getCounter());
        assertEquals(1, left.getCalls());
        assertEquals(1, right.getCalls());

        Field argsField = CoreOperation.class.getDeclaredField("args");
        argsField.setAccessible(true);
        Object[] argsBefore = (Object[]) argsField.get(op);
        assertNotNull(argsBefore);
        assertEquals(2, argsBefore.length);
        assertSame(left, argsBefore[0]);
        assertSame(right, argsBefore[1]);
    }

    @Test
    public void testConstructorStoresBothArguments() throws Exception {
        ConstantExpression left = new ConstantExpression(1);
        ConstantExpression right = new ConstantExpression(2);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Field argsField = CoreOperation.class.getDeclaredField("args");
        argsField.setAccessible(true);
        Object[] args = (Object[]) argsField.get(op);

        assertNotNull(args);
        assertEquals(2, args.length);
        assertSame(left, args[0]);
        assertSame(right, args[1]);
    }
}

