package org.apache.commons.jxpath.ri.model.jdom;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Locale;

import org.apache.commons.jxpath.ri.model.NodePointer;
import org.jdom.Attribute;
import org.jdom.Element;
import org.jdom.Text;
import org.junit.Test;

public class CompareChildNodePointersTests {

    private static class ExposedJDOMNodePointer extends JDOMNodePointer {
        ExposedJDOMNodePointer(final Object node, final Locale locale) {
            super(node, locale);
        }

        int compare(final NodePointer pointer1, final NodePointer pointer2) {
            return compareChildNodePointers(pointer1, pointer2);
        }
    }

    @Test
    public void sameUnderlyingNodeInstanceReturnsZero() {
        Element parent = new Element("parent");
        Text child = new Text("same");
        parent.addContent(child);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);
        NodePointer p1 = new JDOMNodePointer(context, child);
        NodePointer p2 = new JDOMNodePointer(context, child);

        assertEquals(0, context.compare(p1, p2));
    }

    @Test
    public void attributePrecedesChildNode() {
        Element parent = new Element("parent");
        Attribute attr = new Attribute("a", "1");
        Text child = new Text("c");
        parent.setAttribute(attr);
        parent.addContent(child);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);
        NodePointer attrPointer = new JDOMNodePointer(context, attr);
        NodePointer childPointer = new JDOMNodePointer(context, child);

        assertTrue(context.compare(attrPointer, childPointer) < 0);
        assertTrue(context.compare(childPointer, attrPointer) > 0);
    }

    @Test
    public void attributesAreOrderedAccordingToParentAttributeList() {
        Element parent = new Element("parent");
        Attribute first = new Attribute("a", "1");
        Attribute second = new Attribute("b", "2");
        parent.setAttribute(first);
        parent.setAttribute(second);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);
        NodePointer firstPointer = new JDOMNodePointer(context, first);
        NodePointer secondPointer = new JDOMNodePointer(context, second);

        assertTrue(context.compare(firstPointer, secondPointer) > 0);
        assertTrue(context.compare(secondPointer, firstPointer) < 0);
    }

    @Test
    public void childNodesAreOrderedAccordingToParentContentList() {
        Element parent = new Element("parent");
        Text first = new Text("first");
        Text second = new Text("second");
        parent.addContent(first);
        parent.addContent(second);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);
        NodePointer firstPointer = new JDOMNodePointer(context, first);
        NodePointer secondPointer = new JDOMNodePointer(context, second);

        assertTrue(context.compare(firstPointer, secondPointer) < 0);
        assertTrue(context.compare(secondPointer, firstPointer) > 0);
    }

    @Test
    public void comparisonIsIdempotentAndDoesNotModifyInputs() {
        Element parent = new Element("parent");
        Attribute attr = new Attribute("a", "1");
        Text child = new Text("c");
        parent.setAttribute(attr);
        parent.addContent(child);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);
        NodePointer attrPointer = new JDOMNodePointer(context, attr);
        NodePointer childPointer = new JDOMNodePointer(context, child);

        int first = context.compare(attrPointer, childPointer);
        int second = context.compare(attrPointer, childPointer);

        assertEquals(first, second);
        assertTrue(first < 0);
        assertEquals("1", attr.getValue());
        assertEquals("c", child.getValue());
        assertEquals(1, parent.getAttributes().size());
        assertEquals(1, parent.getContent().size());
    }

    @Test
    public void nonElementContextThrowsIllegalStateExceptionForNonAttributeChildComparison() {
        Text nonElementNode = new Text("not-an-element");
        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(nonElementNode, Locale.ENGLISH);

        Element parent = new Element("parent");
        Text child1 = new Text("c1");
        Text child2 = new Text("c2");
        parent.addContent(child1);
        parent.addContent(child2);

        NodePointer p1 = new JDOMNodePointer(context, child1);
        NodePointer p2 = new JDOMNodePointer(context, child2);

        try {
            context.compare(p1, p2);
            fail("Expected IllegalStateException");
        } catch (IllegalStateException ex) {
            assertTrue(ex.getMessage().contains("compareChildNodes called for"));
        }
    }

    @Test
    public void attributesAndChildNodesReturnZeroWhenUnknownNodesAreComparedOnlyAsFallback() {
        Element parent = new Element("parent");
        Attribute attr = new Attribute("a", "1");
        parent.setAttribute(attr);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);

        Element otherParent = new Element("other");
        Attribute unknown1 = new Attribute("x", "1");
        Attribute unknown2 = new Attribute("y", "2");
        otherParent.setAttribute(unknown1);
        otherParent.setAttribute(unknown2);

        NodePointer p1 = new JDOMNodePointer(context, unknown1);
        NodePointer p2 = new JDOMNodePointer(context, unknown2);

        assertEquals(0, context.compare(p1, p2));
    }

    @Test
    public void differentNodeInstancesWithSameLogicalValueAreNotNecessarilyEqual() {
        Element parent = new Element("parent");
        Text child1 = new Text("same");
        Text child2 = new Text("same");
        parent.addContent(child1);
        parent.addContent(child2);

        ExposedJDOMNodePointer context = new ExposedJDOMNodePointer(parent, Locale.ENGLISH);
        NodePointer p1 = new JDOMNodePointer(context, child1);
        NodePointer p2 = new JDOMNodePointer(context, child2);

        int result = context.compare(p1, p2);
        assertNotEquals(0, result);
    }
}

