        RecordingLocationPath(boolean absolute, Step[] steps) {
            super(absolute, steps);
        }

        void setReturnValue(Object returnValue) {
            this.returnValue = returnValue;
        }

        @Override
        protected EvalContext evalSteps(final EvalContext context) {
            this.receivedContext = context;
            return (EvalContext) returnValue;
        }

        Object getReceivedContext() {
            return receivedContext;
        }
    }

    @Test
    public void computeUsesAbsoluteRootContextWhenAbsolute() {
        RecordingRootContext rootContext = new RecordingRootContext();
        RecordingEvalContext absoluteRootContext = new RecordingEvalContext(rootContext, null);
        RecordingEvalContext context = new RecordingEvalContext(rootContext, absoluteRootContext);

        RecordingLocationPath path = new RecordingLocationPath(true, new Step[0]);
        path.setReturnValue(absoluteRootContext);

        Object result = path.compute(context);

        Assert.assertSame(absoluteRootContext, result);
        Assert.assertSame(absoluteRootContext, path.getReceivedContext());
        Assert.assertTrue(context.getRootContextCalled);
        Assert.assertTrue(context.getAbsoluteRootContextCalled);
    }

    @Test
