        Step[] stepsBefore = getStepsViaReflection(path);

        Object result = path.compute(context);

        Assert.assertSame(absoluteRootContext, result);
        Assert.assertSame(stepsBefore, getStepsViaReflection(path));
        Assert.assertEquals(absoluteBefore, isAbsoluteViaReflection(path));
        Assert.assertSame(rootContext, context.getRootContext());
        Assert.assertSame(absoluteRootContext, context.getAbsoluteRootContext());
    }

    @Test
