    @Test(expected = NullPointerException.class)
    public void computeWithNullContextForAbsolutePathThrowsNpeFromContextAccess() {
        RecordingLocationPath path = new RecordingLocationPath(true, new Step[0]);
        path.compute(null);
    }

    private static boolean isAbsoluteViaReflection(LocationPath path) throws Exception {
        Field field = LocationPath.class.getDeclaredField("absolute");
        field.setAccessible(true);
        return field.getBoolean(path);
    }

    private static Step[] getStepsViaReflection(LocationPath path) throws Exception {
        Field field = org.apache.commons.jxpath.ri.compiler.Expression.class.getDeclaredField("steps");
        field.setAccessible(true);
        return (Step[]) field.get(path);
    }
