import org.apache.commons.beanutils.DynaClass;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.Test;

public class AsPathTests {

    @Test
    public void testAsPathReturnsRootWhenParentIsNull() {
        DynaBeanPointer pointer = new DynaBeanPointer(new QName("bean"), (DynaBean) null, Locale.US);
        assertEquals("/", pointer.asPath());
    }

    @Test
    public void testAsPathDelegatesToSuperclassWhenParentExists() {
        DynaBeanPointer parent = new DynaBeanPointer(new QName("parent"), (DynaBean) null, Locale.US);
        DynaBeanPointer child = new DynaBeanPointer((NodePointer) parent, new QName("child"), (DynaBean) null);

        String expected = child.toString();
        assertEquals(expected, child.asPath());
    }

    @Test
    public void testAsPathIsIdempotentForRootPointer() {
        DynaBeanPointer pointer = new DynaBeanPointer(new QName("bean"), (DynaBean) null, Locale.US);

        String first = pointer.asPath();
        String second = pointer.asPath();

        assertEquals("/", first);
        assertEquals(first, second);
    }

    @Test
    public void testAsPathDoesNotChangePointerStateForRootPointer() {
        DynaBeanPointer pointer = new DynaBeanPointer(new QName("bean"), (DynaBean) null, Locale.US);

        String before = pointer.toString();
        String path = pointer.asPath();
        String after = pointer.toString();

        assertEquals("/", path);
        assertEquals(before, after);
    }

    @Test
    public void testAsPathDoesNotChangeParentState() {
        DynaBeanPointer parent = new DynaBeanPointer(new QName("parent"), (DynaBean) null, Locale.US);
        DynaBeanPointer child = new DynaBeanPointer((NodePointer) parent, new QName("child"), (DynaBean) null);

        String parentBefore = parent.toString();
        String childPath = child.asPath();
        String parentAfter = parent.toString();

        assertEquals(child.toString(), childPath);
        assertEquals(parentBefore, parentAfter);
    }

    @Test
    public void testAsPathResultIsNotNullForValidPointers() {
        DynaBeanPointer root = new DynaBeanPointer(new QName("bean"), (DynaBean) null, Locale.US);
        DynaBeanPointer parent = new DynaBeanPointer(new QName("parent"), (DynaBean) null, Locale.US);
        DynaBeanPointer child = new DynaBeanPointer((NodePointer) parent, new QName("child"), (DynaBean) null);

        assertTrue(root.asPath() != null);
        assertTrue(child.asPath() != null);
    }
}

