package org.apache.commons.jxpath.ri.model.dynabeans;

import static org.junit.Assert.assertEquals;

import java.util.Locale;

import org.apache.commons.beanutils.DynaBean;
import org.apache.commons.beanutils.DynaClass;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NullPointer;
import org.junit.Test;

public class AsPathTests {

    @Test
    public void returnsRootPathWhenParentIsNull() {
        DynaBeanPointer pointer = new DynaBeanPointer(new QName(null, "bean"), (DynaBean) null, Locale.ENGLISH);
        assertEquals("/", pointer.asPath());
    }

    @Test
    public void asPathIsIdempotentForRootPointer() {
        DynaBeanPointer pointer = new DynaBeanPointer(new QName(null, "bean"), (DynaBean) null, Locale.ENGLISH);

        String first = pointer.asPath();
        String second = pointer.asPath();

        assertEquals("/", first);
        assertEquals(first, second);
    }

    @Test
    public void returnsSuperclassPathForNonRootPointerAndStripsLeadingSlash() {
        NodePointer parent = new StubParentPointer();
        DynaBeanPointer pointer = new DynaBeanPointer(parent, new QName(null, "bean"), (DynaBean) null);

        assertEquals("parent/bean", pointer.asPath());
    }

    @Test
    public void repeatedCallsForNonRootPointerReturnSameValueAndDoNotMutateParent() {
        StubParentPointer parent = new StubParentPointer();
        DynaBeanPointer pointer = new DynaBeanPointer(parent, new QName(null, "bean"), (DynaBean) null);

        String first = pointer.asPath();
        String second = pointer.asPath();

        assertEquals("parent/bean", first);
        assertEquals(first, second);
        assertEquals(0, parent.getMutationCount());
    }

    @Test
    public void rootConstructorDoesNotDependOnBeanInstance() {
        DynaBeanPointer pointer = new DynaBeanPointer(new QName(null, "bean"), new CountingDynaBean(), Locale.ENGLISH);
        assertEquals("/", pointer.asPath());
    }

    private static final class StubParentPointer extends NodePointer {
        private int mutationCount;

        StubParentPointer() {
            super(null);
        }

        @Override
        public QName getName() {
            return new QName(null, "parent");
        }

        @Override
        public Object getBaseValue() {
            return null;
        }

        @Override
        public void setValue(Object value) {
            mutationCount++;
        }

        @Override
        public boolean isLeaf() {
            return false;
        }

        @Override
        public boolean isCollection() {
            return false;
        }

        @Override
        public int getLength() {
            return 1;
        }

        @Override
        public NodePointer createPath(JXPathContext context) {
            return this;
        }

        @Override
        public NodePointer createPath(JXPathContext context, Object value) {
            return this;
        }

        @Override
        public NodePointer createChild(JXPathContext context, QName name, int index) {
            return new NullPointer(this, name);
        }

        @Override
        public Object getValue() {
            return null;
        }

        @Override
        public Object getImmediateNode() {
            return null;
        }

        @Override
        public String asPath() {
            return "/parent/bean";
        }

        @Override
        public int compareChildNodePointers(NodePointer pointer1, NodePointer pointer2) {
            return 0;
        }

        int getMutationCount() {
            return mutationCount;
        }
    }

    private static final class CountingDynaBean implements DynaBean {
        @Override
        public Object get(String name, int index) {
            return null;
        }

        @Override
        public void set(String name, int index, Object value) {
        }

        @Override
        public boolean contains(String name, String key) {
            return false;
        }

        @Override
        public Object get(String name) {
            return null;
        }

        @Override
        public void set(String name, Object value) {
        }

        @Override
        public Object get(String name, String key) {
            return null;
        }

        @Override
        public void set(String name, String key, Object value) {
        }

        @Override
        public void remove(String name, String key) {
        }

        @Override
        public DynaClass getDynaClass() {
            return null;
        }
    }
}

package org.apache.commons.jxpath.ri.model.dynabeans;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import java.util.Locale;

import org.apache.commons.beanutils.DynaBean;
import org.apache.commons.beanutils.DynaClass;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NullPointer;
import org.junit.Test;

public class AsPathTests {

    private static class SimpleDynaBeanPointer extends DynaBeanPointer {
        public SimpleDynaBeanPointer(NodePointer parent, QName qName, DynaBean dynaBean) {
            super(parent, qName, dynaBean);
        }

        public SimpleDynaBeanPointer(QName qName, DynaBean dynaBean, Locale locale) {
            super(qName, dynaBean, locale);
        }
    }

    private static class SimpleDynaBean implements DynaBean {
        @Override
        public boolean contains(String name, String key) {
            return false;
        }

        @Override
        public Object get(String name) {
            return null;
        }

        @Override
        public Object get(String name, int index) {
            return null;
        }

        @Override
        public Object get(String name, String key) {
            return null;
        }

        @Override
        public DynaClass getDynaClass() {
            return null;
        }

        @Override
        public void remove(String name, String key) {
        }

        @Override
        public void set(String name, Object value) {
        }

        @Override
        public void set(String name, int index, Object value) {
        }

        @Override
        public void set(String name, String key, Object value) {
        }
    }

    @Test
    public void testAsPathReturnsRootWhenParentIsNull() {
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(new QName("bean"), new SimpleDynaBean(), Locale.US);
        assertEquals("/", pointer.asPath());
    }

    @Test
    public void testAsPathIsIdempotentForRootPointer() {
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(new QName("bean"), new SimpleDynaBean(), Locale.US);
        String first = pointer.asPath();
        String second = pointer.asPath();
        assertEquals("/", first);
        assertEquals(first, second);
    }

    @Test
    public void testAsPathDelegatesToSuperclassWhenParentIsNotNull() {
        NodePointer parent = new NullPointer(null, Locale.US);
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(parent, new QName("child"), new SimpleDynaBean());
        assertEquals("/null", pointer.asPath());
    }

    @Test
    public void testAsPathDoesNotModifyParentOrPointerState() {
        NodePointer parent = new NullPointer(null, Locale.US);
        DynaBeanPointer pointer = new SimpleDynaBeanPointer(parent, new QName("child"), new SimpleDynaBean());

        String beforeParent = parent.asPath();
        String first = pointer.asPath();
        String second = pointer.asPath();
        String afterParent = parent.asPath();

        assertEquals("/null", first);
        assertEquals(first, second);
        assertEquals(beforeParent, afterParent);
        assertSame(parent, pointer.getParent());
    }
}
